    public final static MultiblockMachineDefinition INDUSTRIAL_ALTAR = REGISTRATE
            .multiblock("industrial_altar", holder -> new IndustrialAltarMachine(holder))
            .cnLangValue("§b工业血之祭坛")
            .tooltips(industrialAltarLang)
            .tooltipBuilder((stack, tooltip) -> {
                if (GTUtil.isCtrlDown()) {
                    tooltip.add(Component.empty());
                    tooltip.add(industrialAltarctrlLang[0].translate());
                    tooltip.add(industrialAltarctrlLang[1].translate());
                    tooltip.add(industrialAltarctrlLang[2].translate());
                    tooltip.add(industrialAltarctrlLang[3].translate());
                    tooltip.add(industrialAltarctrlLang[4].translate());
                    tooltip.add(industrialAltarctrlLang[5].translate());
                    tooltip.add(industrialAltarctrlLang[6].translate());
                    tooltip.add(industrialAltarctrlLang[7].translate());
                    tooltip.add(industrialAltarctrlLang[8].translate());
                }
            })
            .rotationState(RotationState.NON_Y_AXIS)
            .recipeType(CMRecipeTypes.BLOOD_ALTAR_RECIPES)
            .appearanceBlock(() -> BLANK_RUNE.get())
            .recipeModifiers(IndustrialAltarMachine::recipeModifier)
            .pattern(definition -> FactoryBlockPattern.start()
                    .aisle("ABCBA", "#####")
                    .aisle("BDDDB", "#####")
                    .aisle("CDDDC", "##F##")
                    .aisle("BDDDB", "#####")
                    .aisle("ABEBA", "#####")
                    .where("A", Predicates.blocks(Blocks.SEA_LANTERN))
                    .where("B", Predicates.blocks(BLANK_RUNE.get())
                            .or(Predicates.autoAbilities(definition.getRecipeTypes()).setPreviewCount(0)))
                    .where("E", Predicates.controller(Predicates.blocks(definition.get())))
                    .where("D", CMPredicates.BMRuneBlocks)
                    .where("#", Predicates.any())
                    .where("F", Predicates.blocks(BLOOD_ALTAR.get()))
                    .where("C", Predicates.blocks(Blocks.PRISMARINE_BRICKS))
                    .build())
            .shapeInfos(definition -> {
                List<MultiblockShapeInfo> shapeInfos = new ArrayList<>();
                Function<BlockPattern, MultiblockShapeInfo> toShape = p -> new MultiblockShapeInfo(
                        IndustrialAltarMachine.createPreview(p));
                shapeInfos.add(toShape.apply(definition.getPatternFactory().get()));
                shapeInfos.add(toShape.apply(IndustrialAltarMachine.createLevel3Pattern(definition)));
                shapeInfos.add(toShape.apply(IndustrialAltarMachine.createLevel4Pattern(definition)));
                shapeInfos.add(toShape.apply(IndustrialAltarMachine.createLevel5Pattern(definition)));
                shapeInfos.add(toShape.apply(IndustrialAltarMachine.createLevel6Pattern(definition)));
                return shapeInfos;
            })
            .workableCasingModel(BloodMagicRL("block/blankrune"), CTNHMana.id("block/overlay/manamachine_bm"))
            .register();
